from service import evaluate


def test_owner_mismatch_raises_before_compute():
    calls = []

    def compute():
        calls.append(1)
        return 'x'

    store = {}
    task = {'owner': 'a', 'version': 1, 'job_text': 'j', 'criteria_version': 2}
    profile = {'owner': 'b', 'version': 1}
    try:
        evaluate(store, task, profile, compute)
    except PermissionError:
        assert calls == []
        assert store == {}
    else:
        raise AssertionError('PermissionError not raised')


def test_version_mismatch_returns_none_no_side_effects():
    store = {}
    task = {'owner': 'a', 'version': 2, 'job_text': 'j', 'criteria_version': 2}
    profile = {'owner': 'a', 'version': 1}
    assert evaluate(store, task, profile, lambda: 'x') is None
    assert store == {}


def test_cache_reuse_and_miss():
    store = {}
    task = {'owner': 'a', 'version': 1, 'job_text': 'j', 'criteria_version': 2}
    profile = {'owner': 'a', 'version': 1}
    calls = []
    compute = lambda: (calls.append(1), 'v')[1]
    assert evaluate(store, task, profile, compute) == 'v'
    assert evaluate(store, task, profile, compute) == 'v'
    assert len(calls) == 1
    assert len(store) == 1


def test_key_includes_owner_profile_version_criteria_and_job():
    store = {}
    task = {'owner': 'a', 'version': 2, 'job_text': 'j', 'criteria_version': 3}
    profile = {'owner': 'a', 'version': 2}
    compute = lambda: 'v'
    evaluate(store, task, profile, compute)
    task2 = {'owner': 'a', 'version': 2, 'job_text': 'k', 'criteria_version': 3}
    assert evaluate(store, task2, profile, compute) is not None
    task3 = {'owner': 'a', 'version': 2, 'job_text': 'j', 'criteria_version': 4}
    assert evaluate(store, task3, profile, compute) is not None
    task4 = {'owner': 'a', 'version': 2, 'job_text': 'j', 'criteria_version': 3}
    assert evaluate(store, task4, profile, compute) is not None
    task5 = {'owner': 'b', 'version': 2, 'job_text': 'j', 'criteria_version': 3}
    assert evaluate(store, task5, profile, compute) is not None


def test_compute_exception_propagates_not_cached():
    store = {}
    task = {'owner': 'a', 'version': 1, 'job_text': 'j', 'criteria_version': 2}
    profile = {'owner': 'a', 'version': 1}
    def boom():
        raise ValueError('boom')
    try:
